#' Extract SRA Run Metadata + BioSample Attributes for a BioProject
#'
#' Code generated by Claude AI.
#'
#' Queries NCBI SRA via Entrez for a given BioProject accession, retrieves
#' the run-level metadata (SRR accessions, library info, platform, etc.),
#' then fetches sample-level attributes (genotype, age, tissue, etc.) from
#' the BioSample database, and retrieves FASTQ download links and MD5
#' checksums from the European Nucleotide Archive (ENA). Merges everything
#' together and writes the result to TSV.
#'
#' @param bioproject_id Character. A BioProject accession (e.g., "PRJNA543107").
#' @param output_dir Character. Directory to write the output TSV.
#'   Defaults to the current working directory.
#' @param filename Character or NULL. Custom output filename. If NULL,
#'   defaults to "{bioproject_id}_sra_metadata.tsv".
#' @param retmax Integer. Maximum number of SRA records to retrieve.
#'   Defaults to 500. Increase for very large projects.
#' @param api_key Character or NULL. NCBI API key for higher rate limits.
#'   If NULL, uses the default 3 requests/sec limit.
#'
#' @return A data.frame of the merged metadata (invisibly).
#'
#' @examples
#' # Basic usage
#' metadata <- get_bioproject_metadata("PRJNA543107")
#'
#' # Custom output location
#' metadata <- get_bioproject_metadata("PRJNA543107", output_dir = "results")
#'
#' # With an NCBI API key for faster queries
#' metadata <- get_bioproject_metadata("PRJNA543107", api_key = "your_key_here")

get_bioproject_metadata <- function(bioproject_id,
                                    output_dir = ".",
                                    filename = NULL,
                                    retmax = 500,
                                    api_key = NULL) {

  if (!requireNamespace("rentrez", quietly = TRUE)) {
    stop("rentrez is required. Install with:\n",
         "  install.packages('rentrez')")
  }

  if (!requireNamespace("xml2", quietly = TRUE)) {
    stop("xml2 is required. Install with:\n",
         "  install.packages('xml2')")
  }

  # Validate accession format
  if (!grepl("^PRJNA\\d+$", bioproject_id, ignore.case = TRUE)) {
    stop("bioproject_id should be a BioProject accession (e.g., PRJNA543107).")
  }

  # Set API key if provided
  if (!is.null(api_key)) {
    rentrez::set_entrez_key(api_key)
    message("Using NCBI API key for higher rate limits.")
  }

  # --- Search SRA for all runs in this BioProject ---
  message("Searching SRA for ", bioproject_id, "...")
  search_res <- rentrez::entrez_search(db = "sra",
                                       term = bioproject_id,
                                       retmax = retmax,
                                       use_history = TRUE)

  n_hits <- search_res$count
  if (n_hits == 0) {
    stop("No SRA records for ", bioproject_id, ". Check the accession ID.")
  }

  message("Found ", n_hits, " SRA record(s).")

  if (n_hits > retmax) {
    warning("BioProject has ", n_hits, " records but retmax is ", retmax,
            ". Increase retmax to get all records.")
  }

  # --- Fetch runinfo CSV using web_history for robustness ---
  message("Fetching run metadata...")
  runinfo_text <- rentrez::entrez_fetch(db = "sra",
                                        web_history = search_res$web_history,
                                        rettype = "runinfo",
                                        retmax = retmax)

  # Parse the CSV text into a data frame
  metadata <- read.csv(text = runinfo_text, stringsAsFactors = FALSE)

  # Drop any empty trailing rows (runinfo sometimes has a blank last line)
  metadata <- metadata[metadata$Run != "", , drop = FALSE]

  if (nrow(metadata) == 0) {
    stop("Runinfo returned with no valid rows for ", bioproject_id, ".")
  }

  # --- Fetch BioSample attributes ---
  if ("BioSample" %in% colnames(metadata)) {
    biosample_attrs <- .fetch_biosample_attributes(
      unique(metadata$BioSample[metadata$BioSample != ""])
    )

    if (!is.null(biosample_attrs) && nrow(biosample_attrs) > 0) {
      metadata <- merge(metadata, biosample_attrs,
                        by = "BioSample", all.x = TRUE)
      message("Merged ", ncol(biosample_attrs) - 1,
              " BioSample attribute(s) into metadata.")
    }
  } else {
    message("No BioSample column found in runinfo, skipping sample attributes.")
  }

  # --- Fetch ENA fastq links and MD5s ---
  ena_data <- .fetch_ena_fastq_info(bioproject_id)

  if (!is.null(ena_data) && nrow(ena_data) > 0) {
    # Drop the NCBI download_path column — ENA fastq_ftp replaces it
    metadata$download_path <- NULL

    metadata <- merge(metadata, ena_data,
                      by.x = "Run", by.y = "run_accession",
                      all.x = TRUE)
    message("Added fastq_ftp and fastq_md5 from ENA.")

    # Reorder so Run, fastq_ftp, fastq_md5 are the first 3 columns
    ena_cols <- c("Run", "fastq_ftp", "fastq_md5")
    other_cols <- setdiff(colnames(metadata), ena_cols)
    metadata <- metadata[, c(ena_cols, other_cols), drop = FALSE]
  }

  # --- Clean column names ---
  clean_names <- colnames(metadata)

  # Replace special characters with dots
  clean_names <- gsub("[^A-Za-z0-9_.]", ".", clean_names)

  # Collapse runs of dots
  clean_names <- gsub("\\.{2,}", ".", clean_names)

  # Strip leading/trailing dots
  clean_names <- gsub("^\\.|\\.$", "", clean_names)

  # Handle any resulting duplicates
  if (any(duplicated(clean_names))) {
    clean_names <- make.unique(clean_names, sep = "_")
  }

  colnames(metadata) <- clean_names

  # --- Write output ---
  if (!dir.exists(output_dir)) {
    dir.create(output_dir, recursive = TRUE)
  }

  if (is.null(filename)) {
    filename <- paste0(bioproject_id, "_metadata.tsv")
  }

  output_path <- file.path(output_dir, filename)

  write.table(metadata,
              file = output_path,
              sep = "\t",
              quote = FALSE,
              row.names = FALSE)

  message("Metadata written to: ", output_path)
  message("Runs: ", nrow(metadata), " | Fields: ", ncol(metadata))

  invisible(metadata)
}


#' (Internal) Fetch BioSample Attributes from NCBI
#'
#' Given a vector of BioSample accessions (e.g., SAMN*), fetches the XML
#' records from the BioSample database in batches and parses all sample
#' attributes into a wide-format data frame.
#'
#' @param biosample_ids Character vector of BioSample accessions.
#' @param batch_size Integer. Number of IDs to fetch per request.
#' @return A data.frame with BioSample as the key column and one column
#'   per unique attribute name, or NULL if fetching fails.
#' @keywords internal

.fetch_biosample_attributes <- function(biosample_ids, batch_size = 50) {

  if (length(biosample_ids) == 0) return(NULL)

  message("Fetching BioSample attributes for ", length(biosample_ids),
          " sample(s)...")

  all_attrs <- list()

  batches <- split(biosample_ids,
                   ceiling(seq_along(biosample_ids) / batch_size))

  for (i in seq_along(batches)) {
    batch <- batches[[i]]

    if (length(batches) > 1) {
      message("  Batch ", i, "/", length(batches), "...")
    }

    tryCatch({
      # Build search query: SAMN12345[ACCN] OR SAMN12346[ACCN] OR ...
      query <- paste(paste0(batch, "[ACCN]"), collapse = " OR ")
      search_res <- rentrez::entrez_search(db = "biosample",
                                           term = query,
                                           retmax = length(batch))

      if (length(search_res$ids) == 0) {
        warning("No BioSample records found for batch ", i)
        next
      }

      # Fetch XML
      Sys.sleep(0.35)
      xml_text <- rentrez::entrez_fetch(db = "biosample",
                                        id = search_res$ids,
                                        rettype = "xml")

      # Parse XML and extract attributes
      batch_attrs <- .parse_biosample_xml(xml_text)
      all_attrs <- c(all_attrs, list(batch_attrs))

    }, error = function(e) {
      warning("Failed to fetch BioSample batch ", i, ": ",
              conditionMessage(e))
    })

    # Rate limit between batches
    if (i < length(batches)) Sys.sleep(0.35)
  }

  if (length(all_attrs) == 0) {
    warning("Could not retrieve any BioSample attributes.")
    return(NULL)
  }

  # Combine all batches — use union of all column names
  all_colnames <- unique(unlist(lapply(all_attrs, colnames)))
  combined <- do.call(rbind, lapply(all_attrs, function(df) {
    missing_cols <- setdiff(all_colnames, colnames(df))
    for (col in missing_cols) df[[col]] <- NA_character_
    df[, all_colnames, drop = FALSE]
  }))

  combined
}


#' (Internal) Parse BioSample XML into a Wide Data Frame
#'
#' @param xml_text Character. Raw XML from entrez_fetch.
#' @return A data.frame with one row per BioSample, columns for each attribute.
#' @keywords internal

.parse_biosample_xml <- function(xml_text) {

  doc <- xml2::read_xml(xml_text)
  samples <- xml2::xml_find_all(doc, ".//BioSample")

  rows <- lapply(samples, function(sample_node) {
    # Get the BioSample accession
    accession <- xml2::xml_attr(sample_node, "accession")

    # Get all Attribute nodes
    attr_nodes <- xml2::xml_find_all(sample_node, ".//Attribute")
    attr_names <- xml2::xml_attr(attr_nodes, "attribute_name")
    attr_values <- xml2::xml_text(attr_nodes)

    # Build a named list
    row <- as.list(setNames(attr_values, attr_names))
    row[["BioSample"]] <- accession

    row
  })

  # Get all unique attribute names across samples
  all_names <- unique(c("BioSample", unlist(lapply(rows, names))))

  df <- do.call(rbind, lapply(rows, function(row) {
    vals <- vapply(all_names, function(nm) {
      if (is.null(row[[nm]])) NA_character_ else as.character(row[[nm]])
    }, character(1))
    as.data.frame(t(vals), stringsAsFactors = FALSE)
  }))

  colnames(df) <- all_names
  df
}


#' (Internal) Fetch FASTQ FTP Links and MD5 Checksums from ENA
#'
#' Queries the European Nucleotide Archive (ENA) portal API for a given
#' BioProject to retrieve fastq download links and MD5 checksums.
#'
#' @param bioproject_id Character. A BioProject accession.
#' @return A data.frame with columns: run_accession, fastq_ftp, fastq_md5,
#'   or NULL if the query fails.
#' @keywords internal

.fetch_ena_fastq_info <- function(bioproject_id) {

  ena_url <- paste0(
    "https://www.ebi.ac.uk/ena/portal/api/filereport",
    "?accession=", bioproject_id,
    "&result=read_run",
    "&fields=run_accession,fastq_ftp,fastq_md5",
    "&format=tsv"
  )

  message("Fetching fastq links and MD5s from ENA...")

  tryCatch({
    ena_data <- read.delim(url(ena_url), stringsAsFactors = FALSE)

    if (nrow(ena_data) == 0) {
      warning("ENA returned no records for ", bioproject_id, ".")
      return(NULL)
    }

    ena_data
  }, error = function(e) {
    warning("Failed to fetch ENA data: ", conditionMessage(e),
            "\nThe download_path column will be retained instead.")
    NULL
  })
}
